export const meta = {
  name: 'grill-prep-keychaining',
  description: 'Verify the read key-chaining design against the codebase and surface tensions/implications to drive a grilling interview',
  phases: [
    { title: 'Analyze' },
    { title: 'Verify' },
    { title: 'Critique' },
    { title: 'Synthesize' },
  ],
}

const ROOT = '/Users/myankelev/Code/random/cipher-box'
const DESIGN = `${ROOT}/.planning/design/2026-06-26-sharing-read-keychaining-design.md`
const WALK = `${ROOT}/.planning/design/2026-06-26-sharing-flows-walkthrough.md`
const EXPLAINER = `${ROOT}/landing/src/pages/explainer.astro`

const PREAMBLE = `You are grounding a design review of CipherBox's proposed "read key-chaining" sharing model.

PRIMARY DESIGN DOC (read it): ${DESIGN}
SIBLING FLOWS WALKTHROUGH (read relevant parts): ${WALK}
LANDING EXPLAINER (a more concrete, further-evolved rendering of the same model; read relevant parts): ${EXPLAINER}
CODE ROOT: ${ROOT}

CipherBox is a zero-knowledge encrypted IPFS/IPNS vault; the server is an untrusted relay. Today sharing uses a per-(share,item,keyType) share_keys DB table; the design replaces it with metadata-driven read key-chaining (one wrapped key at a share-root, then O(depth) symmetric AES down the tree) and fixes two revocation gaps (lazy/unsound read-revoke; un-rotatable write-delegation key).

Your job for YOUR ASSIGNED BRANCH:
1. VERIFY every concrete codebase claim the design makes in your branch by READING the actual code (use Read/Grep, cite real file:line you observed). Mark each verified | drifted | not-found, and for drifted/not-found give the actual current state.
2. Surface IMPLICATIONS the design's author/maintainer may not have fully reckoned with (consequences, costs, UX/operational effects, migration hazards).
3. Surface TENSIONS: internal contradictions, gaps, hand-waves, or places the design conflicts with the explainer/walkthrough or with the actual code. Rate severity high|med|low.
4. Produce sharp GRILLING QUESTIONS (the kind that force a precise answer / expose an unconsidered case), each with WHY it matters, your RECOMMENDED answer, and what it dependsOn (other decisions).

Be concrete and skeptical. Do not pad. Prefer fewer, sharper findings over many shallow ones. Cite code you actually read.`

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['branch', 'verifiedClaims', 'implications', 'tensions', 'questions'],
  properties: {
    branch: { type: 'string' },
    verifiedClaims: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false,
        required: ['claim', 'ref', 'status', 'actual'],
        properties: {
          claim: { type: 'string' },
          ref: { type: 'string', description: 'design claim location + the code file:line you checked' },
          status: { type: 'string', enum: ['verified', 'drifted', 'not-found'] },
          actual: { type: 'string', description: 'actual current code state; empty if verified-as-stated' },
        },
      },
    },
    implications: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false, required: ['title', 'detail'],
        properties: { title: { type: 'string' }, detail: { type: 'string' } },
      },
    },
    tensions: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false, required: ['title', 'detail', 'severity'],
        properties: { title: { type: 'string' }, detail: { type: 'string' }, severity: { type: 'string', enum: ['high', 'med', 'low'] } },
      },
    },
    questions: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false, required: ['q', 'why', 'recommendation', 'dependsOn'],
        properties: { q: { type: 'string' }, why: { type: 'string' }, recommendation: { type: 'string' }, dependsOn: { type: 'string' } },
      },
    },
  },
}

const VERIFY_SCHEMA = {
  type: 'object', additionalProperties: false, required: ['branch', 'checks'],
  properties: {
    branch: { type: 'string' },
    checks: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false, required: ['item', 'verdict', 'note'],
        properties: {
          item: { type: 'string' },
          verdict: { type: 'string', enum: ['confirmed', 'refuted', 'adjusted'] },
          note: { type: 'string' },
        },
      },
    },
  },
}

const BRANCHES = [
  {
    key: 'schema-crypto',
    prompt: `BRANCH: Schema + crypto primitive (Design §2.1–2.5).
Cover: the unified Node model (kind discriminator: folder/file/root); the TWO sealed bodies (read-body under readKey, write-body under writeKey — review finding B1); the new AAD-bound seal primitive (sealAesGcmAad/unsealAesGcmAad) and the canonical AAD builder (domain‖nodeId‖kind‖generation‖role); the Rust-enum boundary (model kind as a real enum in crates/fuse, not Option fields).
Verify these specific claims by reading code:
- FolderEntry inline-wraps BOTH folderKeyEncrypted (read) AND ipnsPrivateKeyEncrypted (write) ECIES per child — ${ROOT}/packages/core/src/folder/types.ts (~30-46).
- sealAesGcm/encryptAesGcm take NO aad today — ${ROOT}/packages/crypto/src/aes/seal.ts (~34,42), encrypt.ts (~23). Confirm Web Crypto additionalData is available but unplumbed; confirm each seal mints a fresh random IV.
- The user-privkey unwrap walk the design replaces — ${ROOT}/crates/fuse/src/metadata.rs (~428-453).
- Whether a Rust cipherbox_crypto crate exists for the AAD twin/KAT.
Probe especially: is "two sealed bodies" actually structurally sound given the relay is untrusted? Does role-byte (body/child-readkey/content) buy anything load-bearing? AAD generation-binding interplay with IV reuse (review m3).`,
  },
  {
    key: 'chain-grant',
    prompt: `BRANCH: Chain link, generation-as-single-source-of-truth, read-root grant, content self-seal (Design §2.6–2.9).
Cover: SealedChildRef (childId/kind/name-plaintext-within-sealed-body/ipnsName/generation-mirror/readKeySealed); generation per-node authoritative only on the child's own envelope, mirrors elsewhere are convergence witnesses; the read-root grant row replacing share_keys + fat shares; file content self-sealing under the file node's OWN readKey (single-file-share enabler) and the semantic rename fileKeyEncrypted→content.fileKey.
Verify by reading code:
- decryptFileMetadata is keyed by the PARENT folderKey (the asymmetry blocking single-file share) — ${ROOT}/packages/core/src/file/metadata.ts (~232).
- The current share_keys entity/table + shares entity (fat row) — search ${ROOT}/apps/api/src/shares (entities, service, dtos).
- spawn_file_meta_reencrypt on move/rename — ${ROOT}/crates/fuse/src/metadata.rs (~655) and its caller (design says rename.rs:247 — find the actual rename code path; rename.rs may not exist at that path).
Probe especially: filename plaintext-within-sealed-body leakage on cold nodes; versions[] each carrying its own inline fileKey (rotation cost on revoke); whether "one ECIES at share-root" truly removes ALL per-recipient fan-out for adds.`,
  },
  {
    key: 'flows-scope',
    prompt: `BRANCH: Flows, Big-O, per-grant scope-exit, concurrency unification (Design §3, and the explainer's full flow catalogue + the walkthrough).
Cover: the per-operation cost table; the per-grant (not global) scope-exit caveat (review m2) for move-within-scope; add-during-rotation re-merge requirement (review HIGH-4); the single unification rule "node leaving a reader's reachable scope ⇒ rotateReadFromNode" across the four call sites (delete/rename/move/revoke).
Verify by reading code:
- executeLazyRotation rotates ONLY the share-root folderKey, never descendants — ${ROOT}/apps/web/src/services/share.service.ts (~602-660).
- reWrapForRecipients / addShareKeys fan-out — ${ROOT}/apps/web/src/services/share.service.ts (~337,469).
- The current delete & rename mutation paths in crates/fuse (design cites delete.rs/rename.rs which may not exist at those names — FIND the real files).
Probe especially: the "conservative rotate-on-any-ancestor-set-change" default vs exact per-grant scope computation; whether the explainer's many flows (copy=O(content) re-encrypt; bin/restore; move-between-shares) are consistent with §3's rule set; concurrent owner-mutation-during-rotation correctness.`,
  },
  {
    key: 'rotation-engine',
    prompt: `BRANCH: Read-side resumable rotation engine (Design §4, all subsections).
Cover: CRIT-1 (file nodes MUST mint a new fileKey, not just reseal under new readKey; contentRekeyPending marker); scope-root-first ordering; M1 generation-downgrade fail-closed (generation is NOT signature-covered directly; CID is); HIGH-3 multi-rooted grant re-mint (independently-shared nodes inside a rotated subtree); per-node commit/idempotency/resume + verifySubtreeClean; interaction with CAS-409 and the 6h TEE republisher; the eager-is-committed / lazy-deferred decision (§4.8) and the MED-5 cold-node filename leak.
Verify by reading code:
- IPNS publish authorization: "no ownership/share check" — ${ROOT}/apps/api/src/ipns/ipns.service.ts (~226); anti-rollback gate (~240); forward-only dbSeq+1 CAS (~301-317).
- The 6h republisher re-signs existing bytes at sequence+1, never touches readKey/generation — ${ROOT}/apps/api/src/republish/republish.service.ts (~139,394).
- The strict-resolve path / resolve_sequence_strict + PublishCoordinator.get_lock in crates/fuse (find them).
Probe especially: who runs the O(1e6) rotation, online-owner requirement, multi-session resume realism; the crash-recovery "fresh full rotateOne is the recovery path" double-rotation argument; honest-reader liveness window (MED-6) vs the documented #489/#494 "Folder not loaded" desync; whether generation-monotonicity client check is actually enforceable against a colluding relay.`,
  },
  {
    key: 'write-revocation',
    prompt: `BRANCH: Write-revocation decision — Tier 2 (Design §5 + §8 Q1).
Cover the four candidates: (a) mediated relay→TEE sign, (b) per-grant subkey, (c) full Ed25519 rotation [RECOMMENDED], (d) hybrid. The signing-oracle/confused-deputy argument against mediated; why (b) is dominated by (c); co-writer re-key cost (review m1); the unsolved single-counter sequence race.
Verify by reading code:
- shared-write.ts ECIES-wraps the RAW Ed25519 IPNS private key to the recipient; deleting the row is cryptographically inert — ${ROOT}/packages/sdk/src/share/shared-write.ts (~138-141,311).
- Publish auth is key-possession only; existing.publicKey.equals only ensures the SAME key keeps writing a name — ${ROOT}/apps/api/src/ipns/ipns.service.ts (~226).
- NO synchronous TEE sign endpoint exists; TEE signing is batch-republish-only — ${ROOT}/apps/api/src/tee/tee.service.ts (~110), republish.service.ts.
- k51 name bound to Ed25519 key via deriveIpnsName/publicKeyFromIpnsName; strict-verified from the name — ${ROOT}/crates/fuse/src/publish.rs (~156).
Probe especially: under (c), write-revoke CHANGES the k51 name → parent re-point cascade to root + TEE re-enroll/unenroll (the explainer flow 08 makes this concrete) — is the O(subtree) cascade + co-writer-offline handling actually acceptable? Does the explainer's concrete write-body {ed25519PrivateKey, childLinks[]} (a full write key-chain) contradict the design's "write-body opaque, Tier-2-deferred" stance?`,
  },
  {
    key: 'cutover-tests-fwd',
    prompt: `BRANCH: Blast radius, cutover order, test strategy (Design §6), forward-compat (§7), and open questions §8 Q2–Q6.
Cover: the 6-layer blast radius (core keystone → fuse → sdk → web → api → crypto); the 8-step buildable cutover order; the must-pass-before-merge test list (rotation crash-safety/resume, CRIT-1, HIGH-3, HIGH-4, M1, AAD transplant, TS↔Rust KAT, winfsp); Tier-3 read-side TTL/op-caps being cryptographically unenforceable; and open questions Q2 terminology, Q3 move-within-scope cost, Q4 co-writer offline, Q5 rotation host, Q6 write-recipient-deletes-vs-owner-sub-shares split authority.
Verify/assess by reading where cheap:
- The api:generate + check-api-client pre-commit coupling (CLAUDE.md describes it; confirm scripts/check-api-client.sh exists).
- Whether there is any existing migration/data in production to migrate FROM (is this greenfield or live-data cutover?). Search for share_keys migrations and any seed/real data signals.
- The tests/sdk-e2e suite existence and what it currently covers — ${ROOT}/tests/sdk-e2e (or similar).
Probe especially: is there a migration path for EXISTING vaults/shares or is this a hard cutover (the design gives a build order but NO data migration plan)? Is "no migration" acceptable? Q6's split-authority exposure window. Whether the cutover is realistically one mega-PR or must be staged behind a schema-version flag.`,
  },
  {
    key: 'terminology-crossdoc',
    prompt: `BRANCH: Terminology / domain model + cross-document consistency (domain-modeling discipline).
There is NO CONTEXT.md at repo root yet. The project CLAUDE.md mandates consistent terminology (publicKey, privateKey, rootFolderKey, folderKey, fileKey, keyEpoch, etc.).
Identify terminology decisions and DRIFT across the three artifacts (design doc, walkthrough, explainer) and vs the existing codebase vocabulary:
- readKey (new) vs today's folderKey/fileKey vs the proposed alternative nodeKey (§8 Q2). What does the codebase call these today? (grep packages/core, packages/crypto, CLAUDE.md terminology table.)
- generation (per-node read-key clock) vs keyEpoch (TEE pubkey rotation) vs IPNS sequenceNumber — three distinct counters; confirm the codebase's current names and that they're not conflated.
- The grant row: design §2.8 calls the field readKeyEcies and the row "shares"; the explainer calls it readDescriptorRef and the row "ShareGrant". Is that a contradiction to resolve?
- write material: design says write-body is OPAQUE/Tier-2-deferred (writeBodySealed?: base64); explainer shows a concrete write-body { ed25519PrivateKey, childLinks[] } and writeDescriptorRef on the grant. Flag this as an unresolved model contradiction.
- bin / BinEntry: the explainer & walkthrough have an entire delete→bin / restore / empty-bin model with "no rotation for PRIVATE deletes"; the design doc §3.6 says delete COLLAPSES TO ROTATE. Is the bin model in scope? Does "private delete = no rotation, but the CIDs persist on IPFS" contradict the design's stated reason for rotating deletes? This is likely the single biggest cross-doc gap — dig in.
- copy (explainer only, O(content) re-encrypt): is it covered by the design at all?
Produce questions that force naming decisions and resolve the cross-doc contradictions. Recommend canonical terms.`,
  },
]

phase('Analyze')
const results = await pipeline(
  BRANCHES,
  (b) => agent(`${PREAMBLE}\n\n${b.prompt}`, { label: `analyze:${b.key}`, phase: 'Analyze', schema: SCHEMA }),
  (analysis, b) => {
    if (!analysis) return null
    const drifted = (analysis.verifiedClaims || []).filter((c) => c.status !== 'verified')
    const hot = (analysis.tensions || []).filter((t) => t.severity === 'high')
    if (!drifted.length && !hot.length) {
      return { branch: b.key, analysis, verify: { branch: b.key, checks: [] } }
    }
    const items = [
      ...drifted.map((c) => `CLAIM (${c.status}): "${c.claim}" — analyst says actual: ${c.actual} [${c.ref}]`),
      ...hot.map((t) => `HIGH TENSION: "${t.title}" — ${t.detail}`),
    ].join('\n')
    return agent(
      `${PREAMBLE}\n\nBRANCH ${b.key} — VERIFY PASS. Another analyst flagged the items below. Independently RE-CHECK each against the actual code (Read/Grep). For each: verdict confirmed | refuted | adjusted, with a one-line note citing what you saw. Default to skepticism — only "confirmed" if you personally re-read the code and it holds.\n\n${items}`,
      { label: `verify:${b.key}`, phase: 'Verify', schema: VERIFY_SCHEMA },
    ).then((verify) => ({ branch: b.key, analysis, verify: verify || { branch: b.key, checks: [] } }))
  },
)

const ok = results.filter(Boolean)

phase('Critique')
const briefForCritic = ok
  .map((r) => `## ${r.branch}\nTensions: ${(r.analysis.tensions || []).map((t) => t.title).join('; ')}\nQuestions: ${(r.analysis.questions || []).map((q) => q.q).join(' | ')}`)
  .join('\n\n')

const COMPLETENESS_SCHEMA = {
  type: 'object', additionalProperties: false, required: ['missing'],
  properties: {
    missing: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false, required: ['title', 'detail', 'severity'],
        properties: { title: { type: 'string' }, detail: { type: 'string' }, severity: { type: 'string', enum: ['high', 'med', 'low'] } },
      },
    },
  },
}

const completeness = await agent(
  `${PREAMBLE}\n\nCOMPLETENESS CRITIC. Below are the tensions/questions already found by 7 branch analysts. Read the design doc + explainer + walkthrough and identify what they MISSED — implications, failure modes, cross-doc contradictions, or whole categories of concern not represented below. Focus especially on: (1) cross-cutting issues that span branches; (2) anything in the explainer/walkthrough flows not reconciled with the design; (3) operational/UX/data-migration realities; (4) security edge cases in the rotation/AAD/grant machinery. Do NOT repeat what's already listed. Return only genuinely new items.\n\nALREADY FOUND:\n${briefForCritic}`,
  { label: 'completeness-critic', phase: 'Critique', schema: COMPLETENESS_SCHEMA, effort: 'high' },
)

phase('Synthesize')
const synthInput = ok
  .map((r) => {
    const a = r.analysis
    const claims = (a.verifiedClaims || []).map((c) => `  - [${c.status}] ${c.claim}${c.status !== 'verified' ? ` → ACTUAL: ${c.actual}` : ''} (${c.ref})`).join('\n')
    const impl = (a.implications || []).map((i) => `  - ${i.title}: ${i.detail}`).join('\n')
    const tens = (a.tensions || []).map((t) => `  - [${t.severity}] ${t.title}: ${t.detail}`).join('\n')
    const qs = (a.questions || []).map((q) => `  - Q: ${q.q}\n    why: ${q.why}\n    rec: ${q.recommendation}\n    deps: ${q.dependsOn}`).join('\n')
    const v = (r.verify.checks || []).map((c) => `  - [${c.verdict}] ${c.item} — ${c.note}`).join('\n')
    return `# BRANCH: ${r.branch}\n## Verified claims:\n${claims}\n## Implications:\n${impl}\n## Tensions:\n${tens}\n## Verify-pass results:\n${v}\n## Questions:\n${qs}`
  })
  .join('\n\n')

const completenessText = (completeness?.missing || []).map((m) => `- [${m.severity}] ${m.title}: ${m.detail}`).join('\n')

const synthMarkdown = await agent(
  `You are assembling a GRILLING BATTLE-PLAN for an interactive interview about CipherBox's read key-chaining design. The interviewer will ask the maintainer ONE question at a time, walking the design dependency tree, each question carrying a recommended answer.

From the verified analysis below, produce a TIGHT markdown plan with these sections:
1. "## Verified vs drifted" — a short bullet list of which design codebase-claims hold and which have drifted (with the actual state). This tells the interviewer what NOT to ask (already known) vs what to flag.
2. "## The grilling tree" — questions organized into ordered branches that respect dependencies (foundational/schema decisions first, then rotation, then write-revocation, then cutover/migration, then terminology). For EACH question give: the question (sharp, one precise thing), why it matters in one line, and a recommended answer. Deduplicate aggressively across branches. Order so earlier answers unblock later ones. Aim for the ~20-30 highest-leverage questions total, not everything.
3. "## Cross-doc contradictions to force-resolve" — the design-vs-explainer-vs-walkthrough mismatches (bin model, opaque-vs-concrete write-body, readKeyEcies-vs-readDescriptorRef naming, copy), each as a decision to settle.
4. "## Sharpest single opening question" — name the ONE question to open the interview with, and why it's the highest-leverage starting point.

Return PLAIN MARKDOWN only. Be concise and high-signal; this is a working document, not prose.

=== VERIFIED ANALYSIS (7 branches) ===
${synthInput}

=== COMPLETENESS CRITIC (missed items) ===
${completenessText}`,
  { label: 'synthesize-battle-plan', phase: 'Synthesize', effort: 'high' },
)

return { synthMarkdown, branches: ok, completeness: completeness?.missing || [] }

