phase('Verify')
const results = await parallel(
  CLAIMS.map((c) => () =>
    agent(c.prompt, {
      label: `verify:${c.key}`,
      phase: 'Verify',
      schema: VERDICT_SCHEMA,
      agentType: 'Explore',
      effort: c.effort,
    }).then((v) => ({ key: c.key, ...(v || {}) }))
  )
)

return results.filter(Boolean)

