export const meta = {
  name: 'audit-resolve-republish-threats',
  description: 'Adversarial multi-lens failure/vulnerability audit of the proposed IPNS resolve/republish/TEE redesign',
  phases: [{ title: 'Audit', detail: 'one adversary lens per agent, structured scenarios with verdicts' }],
}

const CONTEXT = `
SYSTEM: CipherBox — zero-knowledge encrypted IPFS/IPNS vault. The RELAY (NestJS API) is UNTRUSTED: it never holds plaintext or any unwrapped key. Clients hold keys and do all crypto client-side. Files are AES-256-GCM, content-addressed on IPFS. Mutable pointers are IPNS records (Ed25519). A "node/v3" read-keychaining redesign is in progress (unified Node{kind:folder|file|root} with a read-body sealed under readKey and a write-body sealed under writeKey; SealedChildRef chains a child's readKey under the parent's readKey; one ECIES grant per recipient at the share-root).

VERIFIED CURRENT-CODE FACTS:
- Clients SELF-SIGN every IPNS record locally with a client-held Ed25519 key (packages/core/src/ipns/create-record.ts). The relay only VERIFIES the signature + checks embedded value == "/ipfs/<cid>", then stores {signedRecord, latestCid, sequenceNumber, publicKey, encryptedIpnsPrivateKey, keyEpoch} per name in table ipns_records (currently named folder_ipns).
- RESOLVE (relay, apps/api/src/ipns/ipns.service.ts resolveRecord ~456-549): relay queries someguy/delegated-routing FIRST, then reads its DB row. Precedence: if dbSeq >= networkSeq return DB record, else return the NETWORK record (strictly ahead). If the DB cache parse returns null (e.g. signedRecord-CID != latestCid guard) it FALLS THROUGH to serving the network record verbatim. Clients resolve ONLY via the relay; client verify = Ed25519 sig + pubKey->name derivation + value==cid + STRICT embedded-seq==response-seq + validity/expiry. NO generation check anywhere.
- PUBLISH GATE (publish path only, ~287-318): first publish embedded seq must == 1; forward publish must == dbSeq+1; == dbSeq is treated as idempotent republish (no increment); < dbSeq rejected (rollback); > dbSeq+1 rejected (jump). Anti-replay: incoming embedded seq must not regress below stored seq. resolveRecord does NOT re-apply this gate to network records.
- IPNS RECORD SELECTION (boxo/go-ipns, verified): higher sequence ALWAYS wins; on EQUAL sequence, LATER validity/EOL wins.
- TEE (apps/tee-worker, Phala CVM in prod): 6-hour background republisher. Decrypts the ECIES-wrapped IPNS private key with an epoch-derived key (with previous-epoch fallback + re-encrypt-for-current-epoch on the keyEpoch grace window). Stateless: zeroes the key immediately, keeps no durable per-name state. Today it signs (cid, seq) scalars supplied by the relay and does seq+1.

RATIFIED REDESIGN DECISIONS (assess scenarios against THIS proposed design, not just current code):
- Q1: GENERATION (a per-node u32 that bumps ONLY on a read-key rotation = scope-exit/revocation; AAD-bound; mirrored in the parent's SealedChildRef) is THE anti-rollback authority. The client tracks a DURABLE per-node {nodeId -> highestGeneration} high-water AND checks the parent-mirror; after resolving a CID it fetches the Node and rejects it if generation < expected. Resolve-source (DB vs network) is a latency/availability layer BENEATH the generation authority. Near-term DB-canonical (DB is written first, ~10-30s ahead of DHT; network-strictly-ahead is an ALARM, not normal). Network-primary is a post-M1 future gated on within-generation consistency.
- Q2: SEQUENCE ADVANCES IFF THE CID CHANGES. Republish NEVER increments — it re-signs the same sequence with a fresh EOL. Increment policy lives in the relay, not the enclave.
- Q3: COLLAPSE the duplicated record state — the canonical ipns_records row is the ONLY source of the TEE's signing inputs; the republish schedule is reduced to scheduling metadata (next_at, failures, status).
- Q4: TEE = RECORD-LEASE-RENEWER. The relay sends the TEE the marshaled EXISTING signedRecord; the TEE parses it, VERIFIES its signature, and re-emits a record with the SAME value(CID) and SAME sequence, only a later EOL. It cannot originate or repoint a CID. Worst a relay can do via the TEE is replay an OLD validly-signed (lower-seq) record for renewal.
- Prior: ADR-0001 write-revocation = full Ed25519 rotation (approach c): rotate the subtree's IPNS keypair(s), changing k51 names, cascading parent re-points to the share-root, TEE re-enroll. ADR-0002 read-revocation = lazy/honest: rotate readKey + generation, mint a fresh fileKey applied lazily (contentRekeyPending); already-distributed ciphertext is presumed leaked (control is who you share with).
`

const SCENARIO_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    lens: { type: 'string' },
    scenarios: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: {
          title: { type: 'string' },
          surface: { type: 'string', description: 'resolve | republish | tee | read-rotation | write-rotation | sequence-eol | concurrency | epoch-key | other' },
          attackChain: { type: 'string', description: 'concrete ordered steps the adversary takes' },
          impact: { type: 'string', description: 'confidentiality / integrity / availability — and what concretely' },
          severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low'] },
          verdict: { type: 'string', enum: ['closed-by-design', 'residual-accepted', 'residual-needs-decision', 'open-gap'] },
          rationale: { type: 'string', description: 'why closed (cite Q1-Q4/ADR) or why residual/open' },
        },
        required: ['title', 'surface', 'attackChain', 'impact', 'severity', 'verdict', 'rationale'],
      },
    },
  },
  required: ['lens', 'scenarios'],
}

const LENSES = [
  {
    key: 'malicious-relay',
    effort: 'high',
    lens: `ACTIVELY MALICIOUS / COMPROMISED RELAY. The relay controls every resolve response a client sees, the inputs it hands the TEE (now constrained to lease-renewal per Q4), the contents of ipns_records, and availability. Enumerate what it can STILL do to a client: serve stale/forked records, exploit the resolve fall-through to the network record, replay old lease-renewals via the TEE, withhold records, manipulate the someguy view, equivocate between clients. For each, does the client-side generation authority (Q1) + strict client verify actually catch it? Probe within-generation rollback (old version, same generation) specifically — generation does NOT distinguish same-generation records.`,
  },
  {
    key: 'revoked-reader',
    effort: 'high',
    lens: `REVOKED READER after a read-key rotation (scope exit). They held the node's old readKey, saw content CIDs, and may have cached metadata. Try to REGAIN access to NEW content or navigation after revocation: roll back to a pre-rotation record, exploit lazy fileKey re-keying (contentRekeyPending), reach un-rotated siblings, use cached SealedChildRefs, read new versions. Which are closed by Q1 generation + ADR-0002 lazy/honest semantics, and which are accepted residuals (already-leaked ciphertext) vs real gaps?`,
  },
  {
    key: 'revoked-writer',
    effort: 'high',
    lens: `REVOKED WRITER after an approach-(c) Ed25519 rotation (ADR-0001). They cached the old signing key. Probe the rotation CASCADE race windows: writes landed under the old k51 name during the parent re-point cascade; an offline co-writer; partial rotation (some subtree nodes rotated, others not); re-pointing not yet propagated; the TEE still enrolled for the old name; resolve serving the old name during transition. What residual writes can they land, and do they reach a reader? What needs a decision (ordering/atomicity of the cascade)?`,
  },
  {
    key: 'keyless-network-attacker',
    effort: 'medium',
    lens: `KEYLESS NETWORK / DHT ATTACKER who only observes PUBLIC IPNS records (no keys, no relay control). They can replay any validly-signed public record to the DHT/someguy and exploit IPNS record selection (higher-seq wins; equal-seq later-EOL wins). Probe: replaying an old record to roll back the DHT view; racing the propagation window after a legit write; same-seq EOL-tiebreak games; whether the relay's DB-canonical resolve (Q1) shields relay-mediated clients while the raw DHT is poisoned for any future direct-resolve / network-primary mode. Which are closed, which are residual for the network-primary future?`,
  },
  {
    key: 'concurrency-races',
    effort: 'high',
    lens: `CONCURRENCY & RACES (no single adversary — correctness/consistency failures, some exploitable). Probe: concurrent client writes to one name (sequence CAS contention); a client write racing the 6-hour TEE lease-renewal; the M1 generation high-water under concurrent rotations or stale client state; add-during-rotation (a child added while its parent's subtree is rotating); multi-rooted grants (a node reachable via two share-roots rotating independently); an offline client returning with a stale generation high-water (false-positive rejection / self-DoS); split-brain between the durable generation store and the network. Flag which are correctness gaps needing a design decision.`,
  },
  {
    key: 'tee-epoch-plane',
    effort: 'medium',
    lens: `TEE & EPOCH-KEY PLANE. The TEE decrypts ECIES-wrapped IPNS keys with epoch-derived keys (previous-epoch fallback + re-encrypt; 4-week keyEpoch grace). Probe: a compromised enclave (what's the blast radius given Q4 lease-renewal-only?); the keyEpoch grace window (old epoch key still accepted); the re-encrypt-for-current-epoch step under a malicious relay; batch-republish cross-contamination; the wrapped key in ipns_records being for the WRONG/rotated identity after an approach-(c) write-rotation (stale enrollment); liveness coupling if the TEE is down for >48h (records expire). Which are closed, which are residual/decision.`,
  },
]

phase('Audit')
const results = await parallel(
  LENSES.map((l) => () =>
    agent(
      `You are performing an adversarial security audit of a PROPOSED redesign of CipherBox's IPNS resolve / republish / TEE-republishing paths.\n\n${CONTEXT}\n\nYOUR ADVERSARY LENS:\n${l.lens}\n\nEnumerate CONCRETE failure/vulnerability scenarios from this lens — be adversarial, try hard to break the proposed design, do not just restate it. For EACH scenario give: a short title, the surface, the concrete attack chain (ordered steps), the impact (confidentiality/integrity/availability + what specifically), a severity, and a VERDICT — one of: closed-by-design (cite which Q1-Q4 decision or ADR closes it), residual-accepted (a known/tolerable residual — explain why tolerable), residual-needs-decision (a residual that requires an explicit design choice), or open-gap (the proposed design missed it entirely). You MAY read code under apps/api/src/ipns, apps/api/src/republish, apps/tee-worker, packages/core/src/ipns, packages/sdk-core/src/ipns to ground a scenario, but prioritize attack-chain reasoning over file dumps. Prioritize scenarios with verdict residual-needs-decision or open-gap — those are the highest value. Return {lens, scenarios:[...]}.`,
      {
        label: `audit:${l.key}`,
        phase: 'Audit',
        schema: SCENARIO_SCHEMA,
        effort: l.effort,
      }
    )
  )
)

return results.filter(Boolean)
